<script>
  import {
    liveGamepiece,
    gameState,
    gameData,
    autoDataLog,
    teleDataLog,
    liveLocation,
    reversedAlliance,
  } from "./stores";

  export let level = 1;
  export let type = "Success";
  export let gameMode = "Auto";

  let dataField = " ";
  let locationField = " ";
  let driverField = " ";

  let displayConeValue = 0;
  let displayCubeValue = 0;



  let driveMap = {
    0: {1: {"NearStation": "DriverLeftStation",
            "FarStation": "DriverRightStation",
            "NearFloor": "DriverLeftFloor",
            "FarFloor": "DriverRightFloor"},
        0: {"NearStation": "DriverRightStation",
            "FarStation": "DriverLeftStation",
            "NearFloor": "DriverRightFloor",
            "FarFloor": "DriverLeftFloor"}},
    1: {0: {"NearStation": "DriverLeftStation",
            "FarStation": "DriverRightStation",
            "NearFloor": "DriverLeftFloor",
            "FarFloor": "DriverRightFloor"},
        1: {"NearStation": "DriverRightStation",
            "FarStation": "DriverLeftStation",
            "NearFloor": "DriverRightFloor",
            "FarFloor": "DriverLeftFloor"}}
        }
 
        // driveMap{reversedAlliance}{AllianceColor}{liveLocation}

  function update() {
    if ((level < 4 && $liveGamepiece[0] == "Cells")) {

    
      if ($gameState === 0) {
        //            $liveLocation = "Floor"; //force pickup location to be floor in auto
        $autoDataLog.push(JSON.parse(JSON.stringify($gameData)));
      } else {
        $teleDataLog.push(JSON.parse(JSON.stringify($gameData)));
      }
      if ($liveLocation == "NearStation" || $liveLocation == "FarStation" || $liveLocation == "NearFloor" || $liveLocation == "FarFloor"){
        driverField = driveMap[$reversedAlliance][$gameData["AllianceColor"]][$liveLocation];
        $gameData[driverField] ++;
      }


      dataField = gameMode + gameLevelMap[level] + $liveGamepiece[0] + type;
      locationField = gameMode + $liveLocation + $liveGamepiece + "Collect";
      console.log("LocationField" + locationField)
      $gameData[dataField] = $gameData[dataField] + 1;
      console.log("LiveGamePiece " + $liveGamepiece);
      $gameData[locationField] = $gameData[locationField] + 1;
      $liveGamepiece = $liveGamepiece.slice(1);
      console.log("Datafield " + dataField);
      console.log("LiveGamePiece " + $liveGamepiece);
      console.log("LiveLocation " + $liveLocation);
      console.log("driverField " + driverField)
      console.log("GameMode" + gameMode);
      console.log("GameData" + $gameData)
      console.log("locationfield" + $liveLocation)
      console.log("DriverReference " + driveMap[$reversedAlliance][$gameData["AllianceColor"]][$liveLocation])
    } else if (level > 3) {
      // Only in tele
      dataField = gameMode + gameLevelMap[level];
      if (type == "Success") {
        $gameData[dataField + "Success"] = $gameData[dataField + "Success"] == 0 ? 1 : 0;
        $gameData[dataField + "Fail"] = 0;
      } else {
        $gameData[dataField + "Fail"] = $gameData[dataField + "Fail"] == 0 ? 1 : 0;
        $gameData[dataField + "Success"] = 0;
      }
      console.log("Datafield " + dataField + $gameData[dataField]);
    }
  }

  let gameLevelMap = {
    1: "Bottom",
    2: "Outer",
    3: "Inner",
    4: "ColorPos",
    5: "ColorRot",
  };
</script>

<div class="indicator">

  {#if level == 1 || level==2 || level==3}
 
  <span class="indicator-item badge badge-accent text-2xl"
    >{$gameData[gameMode + gameLevelMap[level] + "Cells" + type]}</span
  >
  {/if}
 
  <button
    class="btn btn-square btn-outline rounded-md w-20 h-20"
    disabled={$liveGamepiece[0] == 0}
    on:click={update}
  >
    {#if type === "Success"}
      <span
        class="indicator-item indicator-left indicator-left indicator-start badge badge-primary"
        >{gameLevelMap[level]}</span
      >
      {#if level==1}
        <svg version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="266.83852" height="165.78556" viewBox="0,0,266.83852,165.78556"><g transform="translate(-106.58074,-250)"><g fill="none" fill-rule="nonzero" stroke="#00ff00" stroke-width="15" stroke-linecap="butt" stroke-linejoin="miter" stroke-miterlimit="10" stroke-dasharray="" stroke-dashoffset="0" style="mix-blend-mode: normal"><path d="M321.23096,255.39278h-162.46193l-43.52804,-75.39278c0,0 12.56984,-21.77161 19.38592,-33.5774c7.6064,-13.17466 24.14212,-41.81538 24.14212,-41.81538l162.46193,0l43.52804,75.39278z"/></g></g></svg>
      {/if}
      {#if level==2}
        <svg version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="191.43267" height="165.78556" viewBox="0,0,191.43267,165.78556"><g transform="translate(-144.28367,-205)"><g fill="none" fill-rule="nonzero" stroke="#00ff00" stroke-width="15" stroke-linecap="butt" stroke-linejoin="miter" stroke-miterlimit="10" stroke-dasharray="" stroke-dashoffset="0" style="mix-blend-mode: normal"><path d="M283.52804,255.39278h-87.05608l-43.52804,-75.39278l43.52804,-75.39278h87.05608l43.52804,75.39278z"/></g></g></svg>
      {/if}
      {#if level==3}
        <svg version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="191.43267" height="165.78556" viewBox="0,0,191.43267,165.78556"><g transform="translate(-144.28366,-205)"><g fill="none" fill-rule="nonzero" stroke="#00ff00" stroke-linecap="butt" stroke-linejoin="miter" stroke-miterlimit="10" stroke-dasharray="" stroke-dashoffset="0" style="mix-blend-mode: normal"><path d="M283.52804,255.39278h-87.05608l-43.52804,-75.39278l43.52804,-75.39278h87.05608l43.52804,75.39278z" stroke-width="15"/><path d="M198.88933,180c0,-22.7048 18.40588,-41.11067 41.11067,-41.11067c22.7048,0 41.11067,18.40588 41.11067,41.11067c0,22.7048 -18.40588,41.11067 -41.11067,41.11067c-22.7048,0 -41.11067,-18.40588 -41.11067,-41.11067z" stroke-width="12.5"/></g></g></svg>
      {/if}
      {#if level == 4}
        {#if $gameData[gameMode + gameLevelMap[level] + type] == 1}
          <svg version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink ="http://www.w3.org/1999/xlink" width="189.33368" height="190.74299" viewBox="0,0,189.33368,190.74299"><g transform="translate(-145.33316,-220)"><g fill-rule="nonzero" stroke="#000000" stroke-linecap="butt" stroke-linejoin="miter" stroke-miterlimit="10" stroke-dasharray="" stroke-dashoffset="0" style="mix-blend-mode: normal"><path d="M280.18471,96.34594c40.56108,21.85064 59.20609,58.6173 51.94435,102.38401c-2.09347,12.62627 -7.58885,27.21517 -13.86927,36.76665c-3.07479,4.57948 -13.86927,15.63564 -19.75717,20.1497c-5.42995,4.18695 -19.10296,10.79448 -29.11239,14.19638c-11.57953,3.85984 -18.97212,4.84116 -32.2526,4.44863c-20.54222,-0.58879 -34.93486,-5.49537 -51.68266,-17.40201c-19.49549,-13.93469 -34.7386,-38.1405 -39.12181,-62.21546c-1.57011,-8.57016 -1.63553,-23.81328 -0.06542,-32.05634c3.79442,-20.28054 14.5889,-39.51434 29.70118,-53.05651c15.24311,-13.54217 31.53297,-20.86933 52.53314,-23.42075c15.89733,-2.02805 36.70123,2.09347 51.68266,10.20569zM224.24968,98.24315c-9.94401,1.76637 -25.84133,7.458 -25.84133,9.2898c0,0.45795 5.23369,9.74774 11.57953,20.60764c6.34585,10.8599 13.73843,23.55159 16.42069,28.13107c4.44863,7.58885 5.03742,8.3739 6.54211,8.17764c1.17758,-0.13084 1.83179,-0.71963 2.1589,-1.83179c0.58879,-2.02805 0.71963,-62.93509 0.19626,-64.37436c-0.52337,-1.30842 -3.729,-1.30842 -11.05616,0zM239.55821,97.58894c-0.39253,3.27105 0.26168,54.29951 0.78505,58.6173c0.78505,7.32716 0.9159,7.71969 3.46732,7.71969c2.35516,0 1.43926,1.37384 14.00011,-20.93475c4.12153,-7.39258 8.17764,-14.45806 8.96269,-15.70106c0.78505,-1.30842 3.59816,-6.14958 6.215,-10.72906c3.92527,-7.00006 4.51406,-8.57016 3.79442,-9.2898c-1.57011,-1.57011 -12.88796,-6.08416 -19.43006,-7.78511c-6.86921,-1.70095 -17.66369,-2.87853 -17.79454,-1.89721zM193.24008,109.69184c-1.30842,0.06542 -8.96269,6.215 -13.0188,10.33653c-4.6449,4.77574 -11.90664,14.65432 -11.90664,16.15901c0,0.45795 4.6449,3.53274 10.33653,6.86921c21.4